CashMine practical task API
===========================

A test backend for the CashMine React Native practical task. All data is made up and nothing here
moves real money. Treat it like a real remote server: requests can be slow, and any request can fail.

Base URL: https://task-api.cashmine.io

Authentication
--------------

Send your token from the task email on every /v1 request:

    Authorization: Bearer <token>

Your data belongs to your token only. It starts fresh with your first request and includes about
30 days of history. The token stops working at the time given in your task email.

Conventions
-----------

- JSON in and out. Times are ISO 8601 strings in UTC.
- Amounts are decimal strings in the asset's own unit, for example "0.0005" (BTC). They are never
  JSON numbers. Each asset allows at most `decimals` decimal places. Write them as digits with an
  optional dot and more digits, and no leading zeros: "0.5" and "12" are fine; ".5", "1.", "05"
  and "1e-3" are not.
- CORS is open to any origin, so you can call the API from a web app.

Errors
------

    { "error": { "code": "VALIDATION", "message": "...", "field": "amount" } }

    HTTP  code                  meaning
    400   VALIDATION            the request is invalid; `field` names the field when there is one
    401   UNAUTHORIZED          token missing, invalid or expired
    404   NOT_FOUND             unknown endpoint or id
    409   IDEMPOTENCY_MISMATCH  an Idempotency-Key was reused with a different body
    429   RATE_LIMITED          too many requests; wait `retryAfterMs` (also the Retry-After header, in seconds)
    500   SERVER                temporary server error
    503   SERVER                temporary server error
    504   TIMEOUT               the server did not finish in time; the outcome is unknown

A 429 response looks like this:

    { "error": { "code": "RATE_LIMITED", "message": "Too many requests", "retryAfterMs": 2300 } }

Rate limits apply per token.

GET /v1/balances
----------------

    {
      "asOf": "2026-10-20T08:01:15.000Z",
      "items": [
        { "asset": "USDT", "decimals": 6, "available": "820.413207", "pending": "50.12",
          "claiming": "0", "usdPrice": "1.0002" }
      ]
    }

- available: can be claimed now
- pending: payback accrued but not yet confirmed; it becomes available once confirmed
- claiming: the amount in claims that have not completed yet
- usdPrice: the price of one unit in USD

Balances are snapshots, recomputed every 15 seconds. `asOf` is the time of the snapshot, so a claim
you just created may not show up until the next one.

GET /v1/activity?limit=20&cursor=...
------------------------------------

History, newest first. `limit` is 1 to 20 (default 20). Pass `nextCursor` as `cursor` to get the
next page; `nextCursor` is null on the last page.

    {
      "items": [
        { "id": "act_...", "type": "accrual", "asset": "USDT", "amount": "9.81", "status": "confirmed",
          "exchange": "Binance", "createdAt": "...", "relatedId": null }
      ],
      "nextCursor": "..."
    }

- type: accrual (payback earned on an exchange), reversal (an earlier accrual taken back by the
  exchange; relatedId is that accrual's id) or claim (relatedId is the claim id for claims you
  create; null for older claims)
- exchange: where the payback came from; null for claims
- amount: signed; negative for reversals and claims
- status: accrual pending | confirmed; reversal confirmed; claim pending | completed | failed

GET /v1/claim-options?asset=ETH
-------------------------------

    { "asset": "ETH", "minAmount": "0.01", "fee": "0.0012",
      "destinations": [ { "id": "dest_wallet", "label": "Wallet 0x8f3e…a91c" } ] }

The fee is taken from the claimed amount: the user receives amount minus fee.

POST /v1/claims
---------------

Headers:

    Idempotency-Key: <1 to 100 characters, required; a UUID works>

Body:

    { "asset": "ETH", "amount": "0.5", "destinationId": "dest_wallet" }

Rules: minAmount <= amount <= available, and at most `decimals` decimal places. `available` is
checked live, not against the last snapshot.

201 returns a claim. Its amount leaves `available` at once and is counted in `claiming` until the
claim settles.

Repeating a request with the same Idempotency-Key and the same body returns the original claim
(200, header `Idempotent-Replayed: true`) and never creates a second claim, even if the first
response was lost. The same key with a different body returns 409.

Claim:

    { "id": "clm_...", "asset": "ETH", "amount": "0.5", "fee": "0.0012", "receiveAmount": "0.4988",
      "destinationId": "dest_wallet", "status": "pending", "failureReason": null,
      "createdAt": "...", "updatedAt": "..." }

GET /v1/claims/{id}
-------------------

Returns the claim. A pending claim settles within about 20 seconds, to completed or failed. When a
claim fails, its amount returns to available and failureReason says why.
import { API_BASE_URL } from '@/config';

import type { ApiErrorBody } from './types';

/** Server codes from the docs, plus client-side ones. */
export type ApiErrorCodeOrClient =
  | ApiErrorBody['error']['code']
  | 'NETWORK' // request never got a response (offline, DNS, CORS, aborted)
  | 'BAD_RESPONSE'; // response body was not the JSON we expected

export class ApiError extends Error {
  readonly status: number; // 0 when there was no HTTP response
  readonly code: ApiErrorCodeOrClient;
  readonly field?: string;
  readonly retryAfterMs?: number;
  readonly method: string;

  constructor(opts: {
    status: number;
    code: ApiErrorCodeOrClient;
    message: string;
    method: string;
    field?: string;
    retryAfterMs?: number;
  }) {
    super(opts.message);
    this.name = 'ApiError';
    this.status = opts.status;
    this.code = opts.code;
    this.method = opts.method;
    this.field = opts.field;
    this.retryAfterMs = opts.retryAfterMs;
  }

  /** Token missing/invalid/expired: the UI should clear the token. */
  get isUnauthorized(): boolean {
    return this.status === 401 || this.code === 'UNAUTHORIZED';
  }

  /**
   * For non-GET requests: the server may or may not have applied the request
   * (504 TIMEOUT, or no response at all). Retry with the SAME idempotency key
   * or poll; never treat this as "failed".
   */
  get isUnknownOutcome(): boolean {
    if (this.method === 'GET') return false;
    return this.status === 504 || this.code === 'TIMEOUT' || this.code === 'NETWORK';
  }

  /** Worth retrying automatically (for idempotent/GET requests). */
  get isTransient(): boolean {
    return (
      this.code === 'NETWORK' ||
      this.code === 'RATE_LIMITED' ||
      this.code === 'SERVER' ||
      this.code === 'TIMEOUT' ||
      this.status >= 500
    );
  }
}

export function isApiError(e: unknown): e is ApiError {
  return e instanceof ApiError;
}

export type RequestOptions = {
  token: string;
  method?: 'GET' | 'POST';
  query?: Record<string, string | number | undefined | null>;
  body?: unknown;
  headers?: Record<string, string>;
  signal?: AbortSignal;
};

function buildUrl(path: string, query?: RequestOptions['query']): string {
  const url = new URL(path, API_BASE_URL);
  if (query) {
    for (const [k, v] of Object.entries(query)) {
      if (v !== undefined && v !== null) url.searchParams.set(k, String(v));
    }
  }
  return url.toString();
}

function parseRetryAfter(res: Response, bodyMs?: number): number | undefined {
  if (typeof bodyMs === 'number' && Number.isFinite(bodyMs)) return bodyMs;
  const header = res.headers.get('Retry-After');
  if (header == null) return undefined;
  const seconds = Number(header);
  return Number.isFinite(seconds) ? seconds * 1000 : undefined;
}

function fallbackCode(status: number): ApiErrorCodeOrClient {
  if (status === 400) return 'VALIDATION';
  if (status === 401) return 'UNAUTHORIZED';
  if (status === 404) return 'NOT_FOUND';
  if (status === 409) return 'IDEMPOTENCY_MISMATCH';
  if (status === 429) return 'RATE_LIMITED';
  if (status === 504) return 'TIMEOUT';
  if (status >= 500) return 'SERVER';
  return 'BAD_RESPONSE';
}

export async function apiRequest<T>(path: string, opts: RequestOptions): Promise<T> {
  const method = opts.method ?? 'GET';
  const headers: Record<string, string> = {
    Accept: 'application/json',
    Authorization: `Bearer ${opts.token}`,
    ...opts.headers,
  };
  if (opts.body !== undefined) headers['Content-Type'] = 'application/json';

  let res: Response;
  try {
    res = await fetch(buildUrl(path, opts.query), {
      method,
      headers,
      body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
      signal: opts.signal,
    });
  } catch (e) {
    // Let React Query cancellations propagate untouched.
    if (opts.signal?.aborted) throw e;
    throw new ApiError({
      status: 0,
      code: 'NETWORK',
      method,
      message: 'Could not reach the server. Check your connection.',
    });
  }

  let json: unknown = undefined;
  const text = await res.text().catch(() => '');
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = undefined;
    }
  }

  if (!res.ok) {
    const err = (json as Partial<ApiErrorBody> | undefined)?.error;
    throw new ApiError({
      status: res.status,
      code: err?.code ?? fallbackCode(res.status),
      method,
      message: err?.message ?? `Request failed (${res.status})`,
      field: err?.field,
      retryAfterMs: res.status === 429 ? parseRetryAfter(res, err?.retryAfterMs) : err?.retryAfterMs,
    });
  }

  if (json === undefined) {
    throw new ApiError({
      status: res.status,
      code: 'BAD_RESPONSE',
      method,
      message: 'Unexpected response from the server.',
    });
  }
  return json as T;
}
import { apiRequest } from './client';
import type {
  ActivityResponse,
  BalancesResponse,
  Claim,
  ClaimOptions,
  CreateClaimBody,
} from './types';

// Thin typed wrappers over the documented endpoints. Each takes the token
// explicitly so callers (React Query hooks) control where it comes from.

export function getBalances(token: string, signal?: AbortSignal) {
  return apiRequest<BalancesResponse>('/v1/balances', { token, signal });
}

export const ACTIVITY_PAGE_SIZE = 20;

export function getActivity(token: string, cursor?: string | null, signal?: AbortSignal) {
  return apiRequest<ActivityResponse>('/v1/activity', {
    token,
    signal,
    query: { limit: ACTIVITY_PAGE_SIZE, cursor },
  });
}

export function getClaimOptions(token: string, asset: string, signal?: AbortSignal) {
  return apiRequest<ClaimOptions>('/v1/claim-options', { token, signal, query: { asset } });
}

/**
 * Creates a claim. Reuse the same idempotencyKey when retrying after an
 * unknown outcome (504 / network error): the server returns the original
 * claim instead of creating a second one. A new attempt needs a new key.
 */
export function createClaim(token: string, body: CreateClaimBody, idempotencyKey: string) {
  return apiRequest<Claim>('/v1/claims', {
    token,
    method: 'POST',
    body,
    headers: { 'Idempotency-Key': idempotencyKey },
  });
}

export function getClaim(token: string, id: string, signal?: AbortSignal) {
  return apiRequest<Claim>(`/v1/claims/${encodeURIComponent(id)}`, { token, signal });
}
import { useQuery } from '@tanstack/react-query';
import { useAtomValue } from 'jotai';

import { tokenAtom } from '@/state/token';

import { getBalances } from './services';

export const queryKeys = {
  balances: ['balances'] as const,
  activity: ['activity'] as const,
  claimOptions: (asset: string) => ['claim-options', asset] as const,
  claim: (id: string) => ['claim', id] as const,
};

/** Token for API calls; screens behind TokenGate always have one. */
export function useToken(): string {
  const token = useAtomValue(tokenAtom);
  if (!token) throw new Error('useToken used outside TokenGate');
  return token;
}

// Server recomputes balances every 15s, so polling faster is pointless.
export const BALANCES_REFETCH_MS = 15_000;

export function useBalances() {
  const token = useToken();
  return useQuery({
    queryKey: queryKeys.balances,
    queryFn: ({ signal }) => getBalances(token, signal),
    refetchInterval: BALANCES_REFETCH_MS,
  });
}
